// {{if:has_arrayOf}}
type array<T> = T[]
// {{/if:has_arrayOf}}

// {{if:has_lispListOf}}
// TypeScript wrappers flatten a TVM linked list \`[1 [2 [3 null]]]\` to \`[1 2 3]\`
